<?php declare(strict_types=1); use Kulturhus\Verein\MemberChangeRequests;$changeValues=$changeUi['values'];$changeBlocked=$changeUi['blocked'];$changeEmail=trim($changeValues['email'])===$changeValues['email']&&($changeValues['email']===''||filter_var($changeValues['email'],FILTER_VALIDATE_EMAIL))?'email':'text';?>
<?php if($changeBlocked):?><section class="card"><p role="status"><?=e($changeText('Die ursprünglichen Angaben bleiben gesperrt lesbar. Gespeicherten Stand vor einer weiteren Änderung getrennt prüfen.'))?></p><a class="btn btn-outline theme-secondary" target="_blank" rel="noopener" href="<?=e($changeUrl(['submitted_request'=>$changeValues['request_key']]))?>"><?=e($changeText('Gespeicherten Stand dieses Einreichungsvorgangs prüfen'))?></a><a class="btn btn-outline theme-secondary" target="_blank" rel="noopener" href="<?=e(url(['view'=>'portal','tab'=>'own']))?>"><?=e($changeText('Aktuell zugeordnetes Profil in neuem Fenster prüfen'))?></a><label><?=e($changeText('Angaben'))?><textarea class="form-control" readonly rows="10" data-member-change-copy><?=e(implode("\n",array_map(static fn(string $field):string=>$changeText(MemberChangeRequests::FIELDS[$field]).': '.$changeValues[$field],array_keys(MemberChangeRequests::FIELDS))))?></textarea></label></section><?php endif?>
