<h2><?=e($changeText($changeUi['posted']?'Angaben':'Deine aktuellen Angaben'))?></h2><p><?=e($changeText('Ändere die betroffenen Felder. Mit „Zur Prüfung einreichen“ erhält der Vorstand einen Änderungsantrag; die bisherigen Profildaten bleiben zunächst erhalten.'))?></p>
<div class="member-change-fields"><label><?=e($changeText('Vor- und Nachname'))?><input class="form-control" name="name" required maxlength="200" autocomplete="name" value="<?=e($changeValues['name'])?>"></label><label><?=e($changeText('Kontakt-E-Mail'))?><input class="form-control" type="<?=$changeEmail?>" name="email" maxlength="254" autocomplete="email" value="<?=e($changeValues['email'])?>"></label><label><?=e($changeText('Telefon'))?><input class="form-control" type="tel" name="phone" maxlength="80" autocomplete="tel" value="<?=e($changeValues['phone'])?>"></label><label><?=e($changeText('Anschrift'))?><textarea class="form-control" name="address" maxlength="1000" rows="4" autocomplete="street-address" placeholder="<?=e($changeText("Straße und Hausnummer\nPostleitzahl und Ort"))?>"><?=(str_starts_with($changeValues['address'],"\n")||str_starts_with($changeValues['address'],"\r")?"\n":'').e($changeValues['address'])?></textarea></label></div>
